    """Checks if a positive integer n is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def calculate_P(x, y, z):
    """Calculates P = y^x * z^y * x^z, handling edge cases for integer exponents."""
    try:
        # Term 1: y^x
        if y == 0:
            if x > 0:
                term1 = 0
            elif x == 0:
                term1 = 1 # 0^0 convention
            else: # x < 0
                # 0^negative is undefined (infinite)
                return None
        else:
            term1 = y**x

